	if scheme := c.request.Header.Get(HeaderXUrlScheme); isValidScheme(scheme) {
		return scheme
	}
	return "http"
}

// isValidScheme reports whether scheme is one of the schemes `Context#Scheme()`
// is documented to return: `http` or `https`. Schemes are case-insensitive
// (RFC 3986, section 3.1). Values coming from request headers (e.g.
// `X-Forwarded-Proto`) can be arbitrary, so anything else is ignored.
func isValidScheme(scheme string) bool {
	return strings.EqualFold(scheme, "http") || strings.EqualFold(scheme, "https")
}

